def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    chars = []
    seen = set()
    for ch in alphabet:
        if ch not in seen:
            seen.add(ch)
            chars.append(ch)
    width = len(chars)
    pos = {ch: i for i, ch in enumerate(chars)}

    trie = [[-1] * width]
    fail = [0]
    bad = [False]

    def add_node() -> int:
        trie.append([-1] * width)
        fail.append(0)
        bad.append(False)
        return len(trie) - 1

    for word in banned:
        node = 0
        for ch in word:
            c = pos[ch]
            if trie[node][c] < 0:
                trie[node][c] = add_node()
            node = trie[node][c]
        bad[node] = True

    from collections import deque
    queue = deque()
    for c in range(width):
        child = trie[0][c]
        if child >= 0:
            queue.append(child)
        else:
            trie[0][c] = 0
    while queue:
        node = queue.popleft()
        for c in range(width):
            child = trie[node][c]
            if child >= 0:
                link = trie[fail[node]][c]
                fail[child] = link
                bad[child] = bad[child] or bad[link]
                queue.append(child)
            else:
                trie[node][c] = trie[fail[node]][c]

    states = [i for i, flag in enumerate(bad) if not flag]
    index = {state: i for i, state in enumerate(states)}
    size = len(states)
    base = [[0] * size for _ in range(size)]
    for state in states:
        row = base[index[state]]
        for c in range(width):
            nxt = trie[state][c]
            j = index.get(nxt)
            if j is not None:
                row[j] += 1

    def multiply(left, right):
        product = [[0] * size for _ in range(size)]
        for i in range(size):
            left_row = left[i]
            out_row = product[i]
            for k in range(size):
                factor = left_row[k]
                if factor:
                    right_row = right[k]
                    for j in range(size):
                        out_row[j] = (out_row[j] + factor * right_row[j]) % MOD
        return product

    result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    exp = n
    while exp:
        if exp & 1:
            result = multiply(result, base)
        base = multiply(base, base)
        exp >>= 1
    return sum(result[index[0]]) % MOD
